 @Autowired ProfileService profiles;@Autowired MethodService methods;@Autowired MethodSelection ranking;
 @Autowired ObjectScopeLifecycle scopes;@Autowired ObjectLifecycleService lifecycle;@Autowired ObjectCleanupService cleanup;@Autowired ObjectLifecycleGate gate;
 @Autowired TaskContextService context;@Autowired TaskContextGuard contextGuard;@Autowired FeedbackService feedback;
 @Autowired com.dreamcore.workspace.taskwork.TaskWorkService taskWork;@Autowired com.dreamcore.workspace.recommendation.RecommendationService recommendations;
 @Autowired JdbcTemplate db;@Autowired PasswordEncoder passwords;@LocalServerPort int port;
 @MockitoBean RetentionClock clock;
 UUID tenant,owner,admin,reader,platform,space,shared;Instant now;static String encoded;JsonMapper json=new JsonMapper();
 @BeforeEach void setup(){
  now=Instant.now();when(clock.now()).thenReturn(now);tenant=UUID.randomUUID();owner=UUID.randomUUID();admin=UUID.randomUUID();reader=UUID.randomUUID();platform=UUID.randomUUID();space=UUID.randomUUID();shared=UUID.randomUUID();
  if(encoded==null)encoded=passwords.encode("synthetic-version-maintenance");
  for(UUID id:List.of(owner,admin,reader,platform))db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,?)",id,id+"@version.test","合成维护",encoded);
  db.update("INSERT INTO platform_roles(account_id,role) VALUES (?,'PLATFORM_ADMIN')",platform);
  db.update("INSERT INTO tenants(id,name) VALUES (?,'版本维护合成企业')",tenant);
  for(UUID id:List.of(owner,admin,reader))db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,?)",tenant,id,id.equals(admin)?"TENANT_ADMIN":"MEMBER");
  db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'私人','PERSONAL'),(?,?,?,'共享','SHARED')",space,tenant,owner,shared,tenant,admin);
  for(UUID id:List.of(owner,admin,reader))db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,false)",tenant,shared,id);
 }
 @AfterEach void teardown(){db.update("UPDATE conversation_tasks SET status='CANCELLED',lease_token=NULL,lease_until=NULL WHERE tenant_id=? AND status IN('QUEUED','RUNNING')",tenant);db.update("DELETE FROM platform_roles WHERE account_id=?",platform);db.update("DELETE FROM login_attempts WHERE bucket=?",IdentityService.hash("ip:127.0.0.1"));}
 ProfileService.Content content(String text){return new ProfileService.Content(text,"本人明确提供",ProfileService.Status.ACTIVE,null);}
 ProfileService.Value profile(){return profiles.create(owner,tenant,ProfileService.Scope.PERSONAL,owner,"old."+UUID.randomUUID(),ProfileService.Kind.PREFERENCE,content("原始私人偏好正文"),UUID.randomUUID());}
 ProfileService.Value supersede(ProfileService.Value v){return profiles.save(owner,tenant,v.id(),v.revision(),content("明确的新偏好"),UUID.randomUUID());}
 ObjectLifecycleService.Receipt act(UUID actor,UUID t,String kind,UUID version,String action){var i=lifecycle.get(actor,t,kind,version);return lifecycle.act(actor,t,kind,version,UUID.randomUUID(),i.revision(),action,action.equals("PURGE"));}
 void purge(UUID actor,UUID t,String kind,UUID id){act(actor,t,kind,id,"PURGE");cleanup.clean(record(kind,id));}
 UUID record(String kind,UUID id){return db.queryForObject("SELECT id FROM object_lifecycle WHERE kind=? AND object_id=?",UUID.class,kind,id);}
 void denied(int status,Runnable task){assertEquals(status,assertThrows(IdentityException.class,task::run).status);}
 void grant(UUID who,UUID where,String cap){db.update("INSERT INTO governance_capabilities(tenant_id,account_id,workspace_id,capability,granted_by) VALUES (?,?,?,?,?)",tenant,who,where,cap,admin);}
 @Test void explicitOldVersionTrashRestoreEnableAndPermanentErasureKeepCurrentAndMetadata(){
  var old=profile();var current=supersede(old);var trash=act(owner,tenant,"PROFILE_VERSION",old.versionId(),"TRASH");assertEquals(now.plus(Duration.ofDays(30)),trash.current().purgeAfter());
  denied(404,()->profiles.get(owner,tenant,old.id(),1));assertEquals(current.value(),profiles.get(owner,tenant,old.id(),null).value());assertFalse(profiles.history(owner,tenant,old.id(),0,20).items().getLast().bodyAvailable());
  act(owner,tenant,"PROFILE_VERSION",old.versionId(),"RESTORE");assertFalse(gate.active("PROFILE_VERSION",old.versionId()));act(owner,tenant,"PROFILE_VERSION",old.versionId(),"ENABLE");assertEquals(old.value(),profiles.get(owner,tenant,old.id(),1).value());
  purge(owner,tenant,"PROFILE_VERSION",old.versionId());assertEquals("",db.queryForObject("SELECT value FROM profile_versions WHERE id=?",String.class,old.versionId()));assertEquals("",db.queryForObject("SELECT provenance FROM profile_versions WHERE id=?",String.class,old.versionId()));assertTrue(profiles.history(owner,tenant,old.id(),0,20).items().getFirst().bodyAvailable());
  assertEquals(2,profiles.history(owner,tenant,old.id(),0,20).items().size());denied(409,()->act(owner,tenant,"PROFILE_VERSION",old.versionId(),"RESTORE"));
 }
 @Test void currentAndPrivateQualificationsAreServerSideAndTenantProfilesNeedSeparatePurgeGrant(){
  var v=profile();assertEquals(List.of("PROFILE_CURRENT"),lifecycle.preview(owner,tenant,"PROFILE_VERSION",v.versionId()).blockers());denied(409,()->act(owner,tenant,"PROFILE_VERSION",v.versionId(),"TRASH"));denied(404,()->lifecycle.get(admin,tenant,"PROFILE_VERSION",v.versionId()));denied(404,()->lifecycle.get(platform,null,"PROFILE_VERSION",v.versionId()));
  var enterprise=profiles.create(admin,tenant,ProfileService.Scope.TENANT,tenant,"business",ProfileService.Kind.FACT,content("企业业务口径"),UUID.randomUUID());profiles.withdraw(admin,tenant,enterprise.id(),1,UUID.randomUUID());
  denied(403,()->lifecycle.get(reader,tenant,"PROFILE_VERSION",enterprise.versionId()));assertFalse(lifecycle.get(admin,tenant,"PROFILE_VERSION",enterprise.versionId()).actions().contains("PURGE"));denied(403,()->act(admin,tenant,"PROFILE_VERSION",enterprise.versionId(),"PURGE"));grant(admin,null,"LIFECYCLE_PURGE");purge(admin,tenant,"PROFILE_VERSION",enterprise.versionId());
  assertTrue(lifecycle.list(admin,tenant,null,"PROFILE_VERSION",null,0,50).items().stream().anyMatch(i->i.objectId().equals(enterprise.versionId())));
 }
