 UUID runningTask(){UUID c=UUID.randomUUID(),t=UUID.randomUUID(),token=UUID.randomUUID();db.update("INSERT INTO conversations(id,tenant_id,workspace_id,owner_id,title) VALUES (?,?,?,?,'合成上下文')",c,tenant,space,owner);db.update("INSERT INTO conversation_tasks(id,tenant_id,workspace_id,conversation_id,requested_by,prompt,mode,status,execution_class,attempt,lease_token,lease_until) VALUES (?,?,?,?,?,'合成任务','AGENT','RUNNING','verification',1,?,now()+interval '5 minutes')",t,tenant,space,c,owner,token);db.update("INSERT INTO conversation_attempts(task_id,attempt_number,attempt_id,input,status,provenance) VALUES (?,1,?,'合成输入','RUNNING','RECORDED')",t,token);return t;}
 void readProfile(UUID task,ProfileService.Value p){UUID token=db.queryForObject("SELECT lease_token FROM conversation_tasks WHERE id=?",UUID.class,task);context.context(task,token,new TaskContextService.Request("profile_read",null,null,null,p.id(),null,p.revision(),null,null,null,null));}
 @Test void realRuntimeReadCreatesExactRetentionDependencyUntilTaskIsActuallyPurged(){
  var p=profile();UUID t=runningTask();readProfile(t,p);assertEquals(p.id(),db.queryForObject("SELECT reference_id FROM task_context_reads WHERE task_id=?",UUID.class,t));assertEquals("1",db.queryForObject("SELECT version_key FROM task_context_reads WHERE task_id=?",String.class,t));supersede(p);
  assertTrue(lifecycle.preview(owner,tenant,"PROFILE_VERSION",p.versionId()).blockers().contains("PROFILE_TASK_DEPENDENCY"));denied(409,()->act(owner,tenant,"PROFILE_VERSION",p.versionId(),"PURGE"));assertEquals("原始私人偏好正文",db.queryForObject("SELECT value FROM profile_versions WHERE id=?",String.class,p.versionId()));
  purge(owner,tenant,"TASK",t);purge(owner,tenant,"PROFILE_VERSION",p.versionId());assertFalse(gate.active("TASK",t));assertTrue(db.queryForObject("SELECT scrubbed FROM profile_versions WHERE id=?",Boolean.class,p.versionId()));
 }
